export class TokenFile {
  readonly decls: Decl[];
  readonly blocks: Block[];

  constructor(css: string) {
    ({ decls: this.decls, blocks: this.blocks } = parseCss(css));
  }

  /** Names of every custom property declared anywhere in the file. */
  names(): string[] {
